import React from 'react';

const EmergencyListeningUI = () => {
    return (
        <div style={styles.overlay}>
            <div style={styles.box}>
                <div style={styles.icon}>🎤</div>
                <div style={styles.text}>Listening...</div>
                <div style={styles.ambulance}>🚑</div>
            </div>
        </div>
    );
};

const styles = {
    overlay: {
        position: 'fixed',
        top: 0,
        left: 0,
        width: '100vw',
        height: '100vh',
        background: 'red',
        animation: 'flash 1s infinite',
        zIndex: 9999,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        color: 'white',
    },
    box: {
        textAlign: 'center',
    },
    icon: { fontSize: '80px' },
    text: { fontSize: '40px', fontWeight: 'bold', marginTop: '10px' },
    ambulance: { fontSize: '80px', marginTop: '20px' },
};

const style = document.createElement("style");
style.innerHTML = `
@keyframes flash {
    0% { background-color: #ff0000; }
    50% { background-color: #990000; }
    100% { background-color: #ff0000; }
}`;
document.head.appendChild(style);

export default EmergencyListeningUI;
